const $=s=>document.querySelector(s);let state='default',activeClaim='cycling';
const claims={cycling:{quote:'Cycling in the city increased by 24% between 2022 and 2025.',figures:['24%','18%','31%'],scope:['Permanent counters · 12 central routes','Household travel survey · citywide','Volunteer counts · 6 commuter routes'],suggestion:'Sources contain different figures'},history:{quote:'The city began expanding its protected cycle network in 2018.',figures:['2018','2017','2019'],scope:['Capital works programme approved','Pilot routes first opened','First connected corridor completed'],suggestion:'Sources use different milestones'}};
const sources=[{name:'City Transport Office',date:'Mobility report · Sep 2026',short:'Transport Office',excerpt:'Our permanent counters recorded a 24% increase in cycling passages between 2022 and 2025. The comparison covers twelve central routes.'},{name:'Urban Mobility Institute',date:'Travel survey · Aug 2026',short:'Mobility Institute',excerpt:'The household survey estimates an 18% increase in cycling trips across the city from 2022 to 2025, including neighbourhoods without permanent counters.'},{name:'Cycle City Collective',date:'Route counts · Jun 2026',short:'Cycle Collective',excerpt:'Volunteer counts on six commuter routes suggest a 31% increase between 2022 and 2025. Counts were taken on selected weekdays.'}];
function sourceCards(){const c=claims[activeClaim];return sources.map((s,i)=>`<details class="source"><summary class="source-top"><span class="source-icon">${['▤','◈','▧'][i]}</span><div><div class="source-name">${s.name}</div><div class="source-date">${s.date}</div></div><span class="figure">${c.figures[i]}</span></summary><p>${activeClaim==='cycling'?s.excerpt:c.scope[i]+'. This mocked source describes this milestone as the start of the network expansion.'}</p><p>Mock source excerpt · ${c.scope[i]}</p></details>`).join('')}
function roles(expanded=false){return `<div class="section-title">AI perspectives <small>Suggestions only</small></div><div class="suggestion"><button data-role="checker" aria-expanded="${expanded}"><span>✧</span><span><strong>Quellenprüfer</strong><small>${claims[activeClaim].suggestion}</small></span><span class="arrow">${expanded?'−':'+'}</span></button><div class="detail" ${expanded?'':'hidden'}><p>The figures describe different ${activeClaim==='cycling'?'samples and methods':'milestones'}. The sources alone do not establish one definitive ${activeClaim==='cycling'?'citywide increase':'start date'}.</p><p><b>Consider:</b> checking definitions with each source and specifying the scope in your article.</p></div></div><div class="suggestion"><button data-role="historian" aria-expanded="${expanded}"><span>◷</span><span><strong>Historiker</strong><small>Historical context available</small></span><span class="arrow">${expanded?'−':'+'}</span></button><div class="detail" ${expanded?'':'hidden'}><p><b>2017</b> · Pilot routes opened.<br><b>2018</b> · Expansion programme approved.<br><b>2019</b> · First connected corridor completed.</p><p>Mock archive: City Transport Office, network timeline. Consider distinguishing early pilots from the wider programme; this chronology alone does not explain changes in cycling.</p></div></div>`}
function sync(){document.querySelectorAll('[data-state]').forEach(b=>{b.classList.toggle('chosen',b.dataset.state===state);b.setAttribute('aria-pressed',b.dataset.state===state)});document.querySelectorAll('.claim').forEach(c=>c.classList.toggle('selected',state!=='default'&&c.dataset.claim===activeClaim));}
function render(next='default',claim=activeClaim){state=next;activeClaim=claim;sync();const p=$('#panel');$('#clear').title='Return to writing';if(next==='default'){p.innerHTML=`<div class="empty"><div class="empty-symbol">⌁</div><h2>A little more perspective.</h2><p>Select a claim in your draft to see the sources, figures and context behind it.</p><button class="empty-example" id="example"><small>TRY A CONNECTED CLAIM</small>“Cycling in the city increased by 24%…”<span>Explore its evidence <span style="float:right;display:inline;margin:0">↗</span></span></button></div>`;return}const c=claims[claim];p.innerHTML=`${next==='expanded'?'<button class="back" id="back">← Back to claim</button>':''}<div class="label">Selected claim <span>${claim==='cycling'?'01':'02'} / 02</span></div><blockquote class="quote" id="claim-quote"></blockquote><div class="section-title">Connected sources <small>3 mock sources</small></div>${sourceCards()}${next==='expanded'?`<div class="comparison"><div class="section-title">Source comparison</div><table><thead><tr><th>Source</th><th>Reported</th><th>${claim==='cycling'?'Coverage / method':'Milestone'}</th></tr></thead><tbody>${sources.map((s,i)=>`<tr><td>${s.short}</td><td>${c.figures[i]}</td><td>${c.scope[i]}</td></tr>`).join('')}</tbody></table><div class="evidence-note">${claim==='cycling'?'Same period, different measures. These percentages should not be averaged or treated as directly interchangeable.':'Different starting points. These dates refer to pilots, approval and completion, rather than a single shared event.'}</div></div>`:'<button class="primary" id="compare">Compare sources <span>↗</span></button>'}${roles(next==='expanded')}`;$('#claim-quote').textContent=document.querySelector(`[data-claim="${claim}"]`)?.textContent||c.quote;if(matchMedia('(max-width:680px)').matches)$('#context').classList.add('mobile-open')}
$('#panel').addEventListener('click',e=>{if(e.target.closest('#example'))render('selected','cycling');if(e.target.closest('#compare'))render('expanded');if(e.target.closest('#back'))render('selected');const b=e.target.closest('[data-role]');if(b){const d=b.nextElementSibling;d.hidden=!d.hidden;b.setAttribute('aria-expanded',!d.hidden);b.querySelector('.arrow').textContent=d.hidden?'+':'−'}});
document.querySelectorAll('[data-state]').forEach(b=>b.onclick=()=>{render(b.dataset.state,'cycling');if(state==='default')$('#context').classList.remove('mobile-open');selectNav('Writing')});
$('#clear').onclick=()=>{render();$('#context').classList.remove('mobile-open');selectNav('Writing')};$('#context-toggle').onclick=()=>{if(matchMedia('(max-width:680px)').matches)$('#context').classList.toggle('mobile-open');else{render();selectNav('Writing')}};
$('#article').addEventListener('click',e=>{const c=e.target.closest('[data-claim]');if(c){render('selected',c.dataset.claim);selectNav('Writing')}});$('#article').addEventListener('keydown',e=>{const c=e.target.closest('[data-claim]');if(c&&e.key==='Enter'){e.preventDefault();render('selected',c.dataset.claim)}});
document.addEventListener('selectionchange',()=>{const s=getSelection();if(!s||s.isCollapsed)return;const n=s.anchorNode?.parentElement?.closest('[data-claim]');if(n&&s.focusNode&&n.contains(s.focusNode)){render('selected',n.dataset.claim);selectNav('Writing')}});
function selectNav(name){document.querySelectorAll('.nav').forEach(b=>{b.classList.toggle('active',b.dataset.view===name);b.setAttribute('aria-current',b.dataset.view===name?'page':'false')})}
document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>{const v=b.dataset.view;selectNav(v);if(v==='Writing'){render();$('#context').classList.remove('mobile-open');return}$('#context').classList.add('mobile-open');state='default';sync();if(v==='Sources')$('#panel').innerHTML='<div class="label">Story source library</div><p class="resource-intro">Three illustrative sources connected to this draft. Open a source to read its excerpt.</p>'+sourceCards();if(v==='AI Team')$('#panel').innerHTML='<div class="label">Your AI team</div><p class="resource-intro">Explore perspectives on the selected story. No suggestion changes your draft.</p>'+roles(true);if(v==='Research')$('#panel').innerHTML='<div class="label">Research questions</div><h2 style="font:22px Georgia">What do the numbers measure?</h2><p class="resource-intro">Compare the geographic coverage, counting methods and time periods of the three connected sources.</p><button class="primary" id="compare">Explore source comparison <span>↗</span></button>';if(v==='Notes'){$('#panel').innerHTML='<div class="label">Private story notes</div><p class="resource-intro">Keep your questions and reporting next steps here. Saved in this browser.</p><textarea class="notes-input" aria-label="Story notes" placeholder="Questions to follow up…"></textarea>';const n=$('.notes-input');n.value=read('authoria-notes')||'Ask the transport office which routes were included.\nCheck whether all sources use the same baseline.';n.oninput=()=>save('authoria-notes',n.value)}});
function read(k){try{return localStorage.getItem(k)}catch{return null}}function save(k,v){try{localStorage.setItem(k,v);return true}catch{return false}}
const draft=read('authoria-draft');if(draft){try{const d=JSON.parse(draft);$('#title').innerHTML='';$('#title').textContent=d.title;const doc=new DOMParser().parseFromString(d.body,'text/html');doc.querySelectorAll('*').forEach(el=>{if(!['P','H2','SPAN','BR','DIV'].includes(el.tagName)){el.replaceWith(document.createTextNode(el.textContent));return}for(const a of [...el.attributes])if(!['class','data-claim','data-evidence','tabindex','role','aria-label'].includes(a.name))el.removeAttribute(a.name)});$('#article').innerHTML=doc.body.innerHTML}catch{}}
function count(){$('#word-count').textContent=$('#article').innerText.trim().split(/\s+/).filter(Boolean).length+' words'}
document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#context').classList.remove('mobile-open');render();selectNav('Writing')}});$('.brand').onclick=e=>{e.preventDefault();render();selectNav('Writing')};count();render();
